var AWS = require('aws-sdk');
var dynamodb = new AWS.DynamoDB({apiVersion: '2012-08-10'});

exports.handler = (event, context, callback) => {
    var params = {
        Item: {
         "Key": {
            S: event.key
         },
         "Value": {
            S: event.value
         },
        }, 
        TableName: "Your DynamoDB Table Name"
    };
    dynamodb.put(params, function(err, data){
       if(err){
           console.log(err);
           callback(err);
       }else{
